/** @param {NS} ns */
export async function main(ns) {
  const home = 'home';
  const rescanInterval = 30000; // 30s
  let lastScanTime = 0;
  let currentTarget = null;
  let targetMinSecurity = 0;
  let targetMaxMoney = 0;

  // BFS to find all reachable servers
  function findReachable() {
    const visited = new Set();
    const queue = [home];
    visited.add(home);
    const reachable = [];
    while (queue.length > 0) {
      const server = queue.shift();
      reachable.push(server);
      const neighbors = ns.scan(server);
      for (const neighbor of neighbors) {
        if (!visited.has(neighbor)) {
          visited.add(neighbor);
          queue.push(neighbor);
        }
      }
    }
    return reachable;
  }

  // Find best rooted money target
  function findBestTarget(servers) {
    let best = null;
    let bestScore = -1;
    const playerLevel = ns.getHackingLevel();
    for (const server of servers) {
      if (!ns.hasRootAccess(server)) continue;
      const maxMoney = ns.getServerMaxMoney(server);
      if (maxMoney <= 0) continue;
      const minSec = ns.getServerMinSecurity(server);
      const reqLevel = ns.getServerRequiredHackingLevel(server);
      if (reqLevel > playerLevel) continue;
      // Score: prefer higher money, lower min security
      const score = maxMoney - minSec * 1000;
      if (score > bestScore) {
        bestScore = score;
        best = { server, maxMoney, minSec };
      }
    }
    return best;
  }

  ns.tprint('ultra-low-RAM money script starting...');

  while (true) {
    const now = Date.now();
    // Rescan every 30s or if no target
    if (now - lastScanTime > rescanInterval || !currentTarget) {
      const servers = findReachable();
      const candidate = findBestTarget(servers);
      if (candidate) {
        if (!currentTarget || candidate.maxMoney > targetMaxMoney) {
          currentTarget = candidate.server;
          targetMaxMoney = candidate.maxMoney;
          targetMinSecurity = candidate.minSec;
          ns.tprint(`target: ${currentTarget} (max: ${targetMaxMoney})`);
        }
      }
      lastScanTime = now;
    }

    if (!currentTarget) {
      ns.print('no rooted target, sleeping...');
      await ns.sleep(5000);
      continue;
    }

    const sec = ns.getServerSecurityLevel(currentTarget);
    const money = ns.getServerMoneyAvailable(currentTarget);
    const threshold = targetMaxMoney * 0.75;

    if (sec > targetMinSecurity + 5) {
      await ns.weaken(currentTarget);
    } else if (money < threshold) {
      await ns.grow(currentTarget);
    } else {
      await ns.hack(currentTarget);
    }
  }
}

/** @param {NS} ns */
export async function main(ns) {
  const visited = new Set();
  const servers = [];
  const queue = ['home'];

  while (queue.length > 0) {
    const host = queue.shift();
    if (visited.has(host)) continue;
    visited.add(host);

    const scans = ns.scan(host);
    for (const next of scans) {
      if (!visited.has(next)) queue.push(next);
    }

    const rooted = ns.hasRootAccess(host);
    const req = ns.getServerRequiredHackingLevel(host);
    const maxMoney = ns.getServerMaxMoney(host);
    const minSec = ns.getServerMinSecurity(host);
    const curSec = ns.getServerSecurityLevel(host);
    const curMoney = ns.getServerMoneyAvailable(host);
    const maxRam = ns.getServerMaxRam(host);

    servers.push({host, rooted, req, maxMoney, minSec, curSec, curMoney, maxRam});
  }

  servers.sort((a, b) => {
    if (b.rooted !== a.rooted) return b.rooted ? 1 : -1;
    return b.maxMoney - a.maxMoney;
  });

  const hackLvl = ns.getPlayer().skills.hacking;
  let line = `HACK_LVL:${hackLvl}`;

  for (const s of servers) {
    line += `|${s.host}:${s.rooted?1:0}:${s.req}:${s.maxMoney}:${s.minSec}:${Math.round(s.curSec*10)/10}:${s.curMoney}:${s.maxRam}`;
  }

  ns.tprint(line);
}

/** @param {NS} ns */
export async function main(ns) {
  ns.disableLog('sleep');
  ns.disableLog('scan');
  const target_cache = {};
  const roots = new Set();

  const scan = (host, visited = new Set()) => {
    if (visited.has(host)) return;
    visited.add(host);
    const nexts = ns.scan(host);
    for (const next of nexts) scan(next, visited);
    return visited;
  };

  const find_best = () => {
    const visited = scan('home');
    const p = ns.getPlayer();
    let best = null;
    for (const host of visited) {
      if (host === 'home') continue;
      const has_root = ns.hasRootAccess(host);
      if (!has_root) continue;
      const req = ns.getServerRequiredHackingLevel(host);
      const max_m = ns.getServerMaxMoney(host);
      if (p.hacking < req || max_m === 0) continue;
      if (!best || max_m > best.max_m || (max_m === best.max_m && ns.getServerMinSecurityLevel(host) < ns.getServerMinSecurityLevel(best.host))) {
        best = {host, max_m};
      }
    }
    return best;
  };

  let target = find_best();
  if (target) ns.tprint('Target: ' + target.host);

  while (true) {
    if (!target) {
      ns.tprint('No target. Scanning...');
      await ns.sleep(10000);
      target = find_best();
      if (target) ns.tprint('New target: ' + target.host);
      continue;
    }

    const h = target.host;
    const min_sec = ns.getServerMinSecurityLevel(h);
    const cur_sec = ns.getServerSecurityLevel(h);
    const cur_m = ns.getServerMoneyAvailable(h);
    const max_m = target.max_m;

    if (cur_sec > min_sec + 5) {
      await ns.weaken(h);
    } else if (cur_m < 0.75 * max_m) {
      await ns.grow(h);
    } else {
      await ns.hack(h);
    }

    if (Math.random() < 0.01) {
      const new_target = find_best();
      if (new_target && new_target.host !== target.host) {
        ns.tprint('Switched to: ' + new_target.host);
        target = new_target;
      }
    }
  }
}

