export async function main(ns) {
  const targets = ['n00dles', 'foodnstuff', 'sigma-cosmetics', 'joesguns', 'nectar-net', 'hong-fang-tea', 'harakiri-sushi'];
  let target = null;
  let actionCount = 0;
  const recheckInterval = 50;

  while (!target) {
    for (const host of targets) {
      if (ns.hasRootAccess(host) && ns.getServerMaxMoney(host) > 0) {
        target = host;
        break;
      }
    }
    if (!target) await ns.sleep(10000);
  }

  let phase = 0;
  while (true) {
    if (actionCount % recheckInterval === 0) {
      if (!ns.hasRootAccess(target) || ns.getServerMaxMoney(target) <= 0) {
        target = null;
        while (!target) {
          for (const host of targets) {
            if (ns.hasRootAccess(host) && ns.getServerMaxMoney(host) > 0) {
              target = host;
              break;
            }
          }
          if (!target) await ns.sleep(10000);
        }
      }
    }

    const cycle = phase % 10;
    if (cycle < 6) {
      await ns.grow(target);
    } else if (cycle < 9) {
      await ns.weaken(target);
    } else {
      await ns.hack(target);
    }

    phase++;
    actionCount++;
  }
}

